package ie.tudublin

import java.io.File

fun printBoard(board: Array<IntArray>) {
    for (row in board) {
        println(row.joinToString(" ") { if (it == 0) "." else it.toString() })
    }
}

fun main(args: Array<String>) {
    if (args.isEmpty()) {
        println("Usage: sudoku <board-file>")
        return
    }

    val board = File(args[0]).readLines()
        .filter { it.isNotBlank() }
        .map { line -> IntArray(9) { i -> line[i].digitToIntOrNull() ?: 0 } }
        .toTypedArray()

    println("Input:")
    printBoard(board)

    val sudoku = Sudoku(board)
    if (sudoku.solve()) {
        println("\nSolution:")
        printBoard(sudoku.board)
    } else {
        println("\nCould not find a solution")
    }
}